import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<List<Integer>> combine(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        build(n, k, 1, new ArrayList<>(), result);
        return result;
    }

    private void build(int n, int k, int start, List<Integer> current, List<List<Integer>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }
        int remaining = k - current.size();
        int lastStart = n - remaining + 1;
        for (int value = start; value <= lastStart; value++) {
            current.add(value);
            build(n, k, value + 1, current, result);
            current.remove(current.size() - 1);
        }
    }
}
